		if (g_State.bEmuThreadStarted && nextState == CORE_RUNNING)
		{
			for (int i=0; i<numCPUs; i++)
				if (disasmWindow[i])
					SendMessage(disasmWindow[i]->GetDlgHandle(), WM_COMMAND, IDC_GO, 0);
		}
	}

