 void SymbolMap::SaveSymbolMap(const char *filename) const
 {
 	FILE *f = fopen(filename,"w");
 	if (!f)
 		return;
 	fprintf(f,".text\n");
 	for (auto it = entries.begin(), end = entries.end(); it != end; ++it)
 	{
 		const MapEntry &e = *it;
 		fprintf(f,"%08x %08x %08x %i %s\n",e.address,e.size,e.vaddress,e.type,e.name);
