+			break;
+
+		case VC_EQ: // c = s[i] == t[i]; break;
+			comparison = CMPEQSS;
+			compareTwo = true;
+			break;
+
+		case VC_LT: // c = s[i] < t[i]; break;
+			comparison = CMPLTSS;
+			compareTwo = true;
+			break;
+
+		case VC_LE: // c = s[i] <= t[i]; break;
