				UpdateMenus();
				break;

			case ID_OPTIONS_STRETCHDISPLAY:
				g_Config.bStretchToDisplay = !g_Config.bStretchToDisplay;
				UpdateMenus();
				if (gpu)
					gpu->Resized();  // easy way to force a clear...
