 void PreprocessSkyplane(GLRStep* step) {

 	// Do not do anything if the scene is not in VR.
 	if (IsFlatVRScene()) {
 		return;
 	}

 	// Check if it is the step we need to modify.
 	for (auto& cmd : step->commands) {
 		if (cmd.cmd == GLRRenderCommand::BIND_FB_TEXTURE) {
