+// Count leading set bits. For use in UTF-8 decoding. 
+int LeadingOnes(uint8_t byte) {
+	for (int i = 7; i >= 0; i--) {
+		if (!((byte >> i) & 1)) return 7 - i;
+	}
+
+	return 8;
