 inline u32 ComputeMiniHashRange(const void *ptr, size_t sz) {
 	// Switch to u32 units.
 	const u32 *p = (const u32 *)ptr;
 	sz >>= 2;

 	if (sz > 100) {
 		size_t step = sz / 4;
 		u32 hash = 0;
 		for (size_t i = 0; i < sz; i += step) {
 			hash += DoReliableHash32(p + i, 100, 0x3A44B9C4);
 		}
 		return hash;
 	} else {
 		return p[0] + p[sz - 1];
 	}
 }

