+int binary_search(JitBlock blocks[], const u8 *baseoff, int imin, int imax)
+{
+	while (imin < imax)
+	{
+		int imid = (imin + imax) / 2;
+		if (blocks[imid].normalEntry < baseoff)
+			imin = imid + 1;
+		else
+			imax = imid;
+	}
+	if ((imax == imin) && (blocks[imin].normalEntry == baseoff))
+		return imin;
+	else
+		return -1;
