			wokeThreads = true;
		}
		s->waitingThreads.empty();

		// TODO: Should this reschedule?  threads/semaphores fails if it doesn't.
		if (wokeThreads)
			__KernelReSchedule("semaphore deleted");

		return kernelObjects.Destroy<Semaphore>(id);
	}
