	case JOYSTICK_AXIS_ACCELEROMETER_Y:
	case JOYSTICK_AXIS_ACCELEROMETER_Z:
		// Ignore the accelerometer for mapping for now.
		// We use tilt control for these.
		return true;

	default:
		return false;
	}
}

