 	if (breakNext_ == BreakNext::DRAW && !GPUStepping::IsStepping()) {
 		// Break on the first PRIM after a flush.
 		if (primAfterDraw_) {
 			NOTICE_LOG(Log::GeDebugger, "Flush detected, breaking at next PRIM");
 			primAfterDraw_ = false;
 			// Switch to PRIM mode.
 			SetBreakNext(BreakNext::PRIM);
 		}
 	}
 }

