 std::string ReplaceAll(std::string result, const std::string& src, const std::string& dest)
 {
 	size_t pos = 0;

 	if (src == dest)
 		return result;

 	while (1)
 	{
 		pos = result.find(src, pos);
 		if (pos == result.npos)
 			break;
 		result.replace(pos, src.size(), dest);
 		pos += dest.size();
 	}
 	return result;
 }


