+static float HorizontalOverlap(const Bounds &a, const Bounds &b) {
+	if (a.x2() < b.x || b.x2() < a.x)
+		return 0.0f;
+	// okay they do overlap. Let's clip.
+	float maxMin = std::max(a.x, b.x);
+	float minMax = std::min(a.x2(), b.x2());
+	float overlap = minMax - maxMin;
+	if (overlap < 0.0f)
