 void __RtcTmToPspTime(ScePspDateTime &t, tm *val)
 {
 	t.year = val->tm_year + 1900;
 	t.month = val->tm_mon + 1;
 	t.day = val->tm_mday;
 	t.hour = val->tm_hour;
 	t.minute = val->tm_min;
 	t.second = val->tm_sec;
 	t.microsecond = 0;
