 void __RtcTicksToPspTime(ScePspDateTime &t, u64 ticks)
 {
 	int numYearAdd = 0;
 	if(ticks < 1000000ULL)
 	{
 		t.year = 1;
 		t.month = 1;
 		t.day = 1;
 		t.hour = 0;
 		t.minute = 0;
 		t.second = 0;
 		t.microsecond = ticks % 1000000ULL;
