			for (int i = 0; i < GetNumVectorElements(sz); i++) {
				u32 value = s[i];
				d[i * 2] = (value & 0xFFFF) << 16;
				d[i * 2 + 1] = value & 0xFFFF0000;
			}
			oz = V_Pair;
			if (sz == V_Pair) oz = V_Quad;
			break;
		default:
			_dbg_assert_msg_(CPU,0,"Trying to interpret instruction that can't be interpreted");
			break;
		}

		ApplyPrefixD((float*)d,oz);  // Only write mask should be valid
		WriteVector((float*)d,oz,vd);
		PC += 4;
		EatPrefixes();
	}

  void Int_ColorConv(u32 op) 
  {
    int vd = _VD;
    int vs = _VS;
    u32 s[4];
    VectorSize sz = V_Quad;
    ReadVector((float *)s, sz, vs);
    u16 colors[4];
    for (int i = 0; i < 4; i++)
    {
      u32 in = s[i];
      u16 col = 0;
      switch ((op >> 16) & 3)
      {
      case 1:  // 4444
        {
          int a = ((in >> 24) & 0xFF) >> 4;
          int b = ((in >> 16) & 0xFF) >> 4;
          int g = ((in >> 8) & 0xFF) >> 4;
          int r = ((in) & 0xFF) >> 4;
          col = (a << 12) | (b << 8) | (g << 4 ) | (r);
          break;
        }
      case 2:  // 5551
        {
          int a = ((in >> 24) & 0xFF) >> 7;
          int b = ((in >> 16) & 0xFF) >> 3;
          int g = ((in >> 8) & 0xFF) >> 3;
          int r = ((in) & 0xFF) >> 3;
          col = (a << 15) | (b << 10) | (g << 5) | (r);
          break;
        }
      case 3:  // 565
        {
          int b = ((in >> 16) & 0xFF) >> 3;
          int g = ((in >> 8) & 0xFF) >> 2;
          int r = ((in) & 0xFF) >> 3;
          col = (b << 11) | (g << 5) | (r); 
          break;
        }
      }
      colors[i] = col;
    }
    u32 ov[2] =  {(u32)colors[0] | (colors[1] << 16), (u32)colors[2] | (colors[3] << 16)};
    WriteVector((const float *)ov, V_Pair, vd);
    PC += 4;
    EatPrefixes();
  }

