diff --git a/GPU/GLES/FragmentTestCache.cpp b/GPU/GLES/FragmentTestCache.cpp
new file mode 100644
index 0000000000..f562f65fed
--- /dev/null
+++ b/GPU/GLES/FragmentTestCache.cpp
@@ -0,0 +1,167 @@
+// Copyright (c) 2014- PPSSPP Project.
+
