 Psmf::Psmf(u32 data) {
 	headerOffset = data;
 	magic = Memory::Read_U32(data);
 	version = Memory::Read_U32(data + 4);
 	streamOffset = bswap32(Memory::Read_U32(data + 8));
 	streamSize = bswap32(Memory::Read_U32(data + 12));
 	streamDataTotalSize = bswap32(Memory::Read_U32(data + 0x50));
