 	u32 texaddr = entry.addr + texaddrOffset;

 	bool texInVRAM = Memory::IsVRAMAddress(texaddr);
 	bool fbInVRAM = Memory::IsVRAMAddress(fb_address);

 	if (texInVRAM != fbInVRAM) {
 		// Shortcut. Cannot possibly be a match.
 		return false;
