 std::string SavedataParam::GetSpaceText(int size)
 {
 	char text[50];

 	if(size < 1024)
 	{
 		sprintf(text,"%d B",size);
 		return std::string(text);
 	}

 	size /= 1024;

 	if(size < 1024)
 	{
 		sprintf(text,"%d KB",size);
 		return std::string(text);
 	}

 	size /= 1024;

 	if(size < 1024)
 	{
 		sprintf(text,"%d MB",size);
 		return std::string(text);
 	}

 	size /= 1024;
 	sprintf(text,"%d GB",size);
 	return std::string(text);
 }

