+static inline u32 DecodeRGBA4444(u16 src)
+{
+	u8 r = (src>>12) & 0x0F;
+	u8 g = (src>>8) & 0x0F;
+	u8 b = (src>>4) & 0x0F;
+	u8 a = (src>>0) & 0x0F;
