+static inline u32 DecodeRGBA5551(u16 src)
+{
+	u8 r = src & 0x1F;
+	u8 g = (src >> 5) & 0x1F;
+	u8 b = (src >> 10) & 0x1F;
+	u8 a = (src >> 15) & 0x1;
