+		ERROR_LOG(G3D, "Error in shader compilation!\n");
+		ERROR_LOG(G3D, "Info log: %s\n", infoLog);
+		ERROR_LOG(G3D, "Shader source:\n%s\n", (const char *)code);
+#ifdef SHADERLOG
+		OutputDebugStringUTF8(infoLog);
