 	static constexpr float DEADZONE_THRESHOLD = 0.2f;
 	static constexpr float DEADZONE_SCALE = 1.0f / (1.0f - DEADZONE_THRESHOLD);

 	FPSLimit &limitMode = PSP_CoreParameter().fpsLimit;
