+void CtrlDisAsmView::scanFunctions()
+{
+	u32 pos = windowStart;
+	u32 windowEnd = windowStart+visibleRows*instructionSize;
+
+	visibleFunctionAddresses.clear();
+	strayLines.clear();
+
+	while (pos < windowEnd)
+	{
+		SymbolInfo info;
