+	auto trace = executed_blocks.get_content();
+	for (auto index : trace) {
+		auto& block_info = trace_info[index];
+		flush_block_to_file(block_info);
+	}
+
+	INFO_LOG(Log::JIT, "Trace flushed, closing the file...");
