+int getChunkOffset(u8* riff, int limit, int chunkMagic, int offset) {
+	for (int i = offset; i <= limit - 8;) {
+		if (getBufValue((int*)riff, i) == chunkMagic)
+			return i;
+		// Move to next chunk
+		int chunkSize = getBufValue((int*)riff, i + 4);
+		i += chunkSize + 8;
+	}
+
+	return -1;
