+	u8 headerCode0 = getBufValue(riff, fmtChunkOffset + 0x31);
+	u8 headerCode1 = getBufValue(riff, fmtChunkOffset + 0x32);
+	u8 headerCode2 = getBufValue(riff, fmtChunkOffset + 0x33);
