+				*startsample = getBufValue((int*)riff, loopInfoAddr + 8) - atracSampleOffset;
+			if (endsample)
+				*endsample = getBufValue((int*)riff, loopInfoAddr + 12) - atracSampleOffset;
+			int playcount = getBufValue((int*)riff, loopInfoAddr + 20);
+			if (playcount != 1)
