+
+int getRIFFChannels(u8* riff, int bufsize)
+{
+	const int firstChunkOffset = 12;
+	int fmtChunkOffset = getChunkOffset(riff, bufsize, FMT_CHUNK_MAGIC, firstChunkOffset);
+	if (fmtChunkOffset < 0) 
+		return 0;
