 void PSPOskDialog::HackyGetStringWide(std::string& _string, const u32 em_address)
 {
 	char stringBuffer[2048];
 	char *string = stringBuffer;
 	char c;
 	u32 addr = em_address;
 	while ((c = (char)(Memory::Read_U16(addr))))
 	{
 		*string++ = c;
 		addr+=2;
 	}
 	*string++ = '\0';
 	_string = stringBuffer;
 }


