+	std::unique_lock<std::mutex> lock(mutex);
+	if (start + size <= capacity) {
+		memcpy(buf, buf_ + start, size);
+		start += size;
+	} else {
+		memcpy(buf, buf_ + start, capacity - start);
+		size -= capacity - start;
+		memcpy(buf + capacity - start, buf_, size);
+		start = size;
+	}
