+	std::unique_lock<std::mutex> lock(mutex);
+	buf_ = new u8[newSize];
+	if (end >= start) {
+		memcpy(buf_, oldbuf + start, availableSize);
+	} else {
+		memcpy(buf_, oldbuf + start, capacity - start);
+		memcpy(buf_ + capacity - start, oldbuf, availableSize - (capacity - start));
+	}
+	start = 0;
+	end = availableSize;
+	capacity = newSize;
+	delete[] oldbuf;
+	lock.unlock();
+}
