+			workers[i]->Process(std::bind(loop, s, std::min(s+chunk,upper)));
+		}
+		for(int i=0; i<numThreads; ++i) {
+			workers[i]->WaitForCompletion();
+		}
+	} else {
+		loop(lower, upper);
+	}
