 				ERROR_LOG(G3D, "Texture replacement changed since header read: %s", info.file.c_str());
+				SetState(ReplacementState::NOT_FOUND);
 				cleanup();
 				return;
 			}

 			out.resize(info.w * info.h * 4);
 			if (w == info.w) {
 				memcpy(&out[0], image, info.w * 4 * info.h);
 			} else {
