 		VirtualFramebuffer *vfb = vfbs_[i];

 		FramebufferInfo info;
 		info.fb_address = vfb->fb_address;
 		info.z_address = vfb->z_address;
 		info.format = vfb->format;
 		info.width = vfb->width;
 		info.height = vfb->height;
 		info.fbo = vfb->fbo;
 		list.push_back(info);
 	}

 	return list;
 }

