+		// Ignore for now.
+		glstate.depthTest.disable();
+		glstate.colorMask.set(GL_FALSE, GL_FALSE, GL_FALSE, GL_TRUE);
+		glstate.stencilTest.enable();
+		glstate.stencilOp.set(GL_KEEP, GL_KEEP, GL_KEEP);  // don't modify stencil�
