+
+		INFO_LOG(SCEGE, "Creating FBO for %08x : %i x %i x %i", vfb->fb_address, vfb->width, vfb->height, vfb->format);
+
+		vfb->last_frame_render = gpuStats.numFlips;
+		vfb->last_frame_used = 0;
