 static Stick NormalizedDeadzoneFilter(short x, short y) {
 		Stick s;
 		s.x = (float)x / 10000.f;
 		s.y = -((float)y / 10000.f);

 		// Expand and clamp. Hack to let us reach the corners on most pads.
 		s.x = std::min(1.0f, std::max(-1.0f, s.x * 1.2f));
 		s.y = std::min(1.0f, std::max(-1.0f, s.y * 1.2f));

 		return s;
 }

