 			emit->STR(CTXREG, r, 4 * ar[r].mipsReg);
 		// IMMs won't be in an ARM reg.
 		mr[ar[r].mipsReg].loc = ML_MEM;
 		mr[ar[r].mipsReg].reg = INVALID_REG;
 		mr[ar[r].mipsReg].imm = 0;
 	} else {
 		ERROR_LOG(HLE, "Dirty but no mipsreg?");
 	}
 	ar[r].isDirty = false;
 	ar[r].mipsReg = -1;
