 void ArmRegCache::FlushMipsReg(MIPSReg r) {
 	switch (mr[r].loc) {
 	case ML_IMM:
 		// IMM is always "dirty".
 		emit->ARMABI_MOVI2R(R0, mr[r].imm);
 		emit->STR(CTXREG, R0, GetMipsRegOffset(r));

