 static std::string EscapeHash(std::string_view value) {
 	std::string result = "";

 	for (size_t pos = 0; pos < value.size(); ) {
 		size_t next = value.find('#', pos);
 		if (next == value.npos) {
 			result += value.substr(pos);
 			pos = value.npos;
 		} else {
 			result += value.substr(pos, next - pos);
 			result += "\\#";
 			pos = next + 1;
 		}
 	}

 	return result;
 }

