 {
 	u32 error;
 	SceUID threadID = (SceUID) userdata;
 	SceUID verify = __KernelGetWaitID(threadID, WAITTYPE_HLEDELAY, error);
 	// The top 32 bits of userdata are the top 32 bits of the 64 bit result.
