 	}

 	Screen *popupScreen = new ListPopupScreen(text_, choices, *value_ - minVal_,
 		std::bind(&PopupMultiChoice::ChoiceCallback, this, placeholder::_1));
 	screenManager_->push(popupScreen);
 	return EVENT_DONE;
