+			u32 sourcemask = mask >> pos;
+			u32 destmask = ~(sourcemask << pos);
+			if (gpr.IsImm(rs)) {
+				u32 inserted = (gpr.GetImm(rs) & sourcemask) << pos;
+				if (gpr.IsImm(rt)) {
+					gpr.SetImm(rt, (gpr.GetImm(rt) & destmask) | inserted);
+					return;
+				}
