 {
 	int listid = userdata >> 32;
 	GPUSyncType type = (GPUSyncType) (userdata & 0xFFFFFFFF);
 	bool wokeThreads = __GeTriggerWait(type, listid);
 	gpu->SyncEnd(type, listid, wokeThreads);
 }

