 {
 	u64 geTicks = gpu->GetTickEstimate();
 	if (geTicks != 0)
 	{
 		if (CoreTiming::GetTicks() > geTicks + usToCycles(geBehindThresholdUs)) {
 			u64 diff = CoreTiming::GetTicks() - geTicks;
 			gpu->SyncThread();
 			CoreTiming::Advance();
 		}
