 	if (wrap) {
 		bool rotated = (align & (ROTATE_90DEG_LEFT | ROTATE_90DEG_RIGHT)) != 0;
 		WrapString(toDraw, str, rotated ? bounds.h : bounds.w, wrap);
 	}

 	DrawString(target, toDraw.c_str(), x, y, color, align);
 }

