{
	atracsection.lock();
	for (auto it = audioMap.begin(); it != audioMap.end(); ++it) {
		delete it->second;
	}
	audioMap.clear();
	atracsection.unlock();
	CoUninitialize();
	FreeFilterLibrary(0);
}

