void __NetDoState(PointerWrap &p) {
	auto s = p.Section("sceNet", 1, 3);
	if (!s)
		return;

	auto cur_netInited = netInited;
	auto cur_netInetInited = netInetInited;
	auto cur_netApctlInited = netApctlInited;

	p.Do(netInited);
	p.Do(netInetInited);
	p.Do(netApctlInited);
	p.Do(apctlHandlers);
	p.Do(netMallocStat);
	if (s < 2) {
		netDropRate = 0;
		netDropDuration = 0;
	} else {
		p.Do(netDropRate);
		p.Do(netDropDuration);
	}
	if (s < 3) {
		netPoolAddr = 0;
		netThread1Addr = 0;
		netThread2Addr = 0;
	} else {
		p.Do(netPoolAddr);
		p.Do(netThread1Addr);
		p.Do(netThread2Addr);
	}
	// Let's not change "Inited" value when Loading SaveState in the middle of multiplayer to prevent memory & port leaks
	if (p.mode == p.MODE_READ) {
		netApctlInited = cur_netApctlInited;
		netInetInited = cur_netInetInited;
		netInited = cur_netInited;
	}
}

