+	// Load the row dither matrix entry (will still need to get the X.)
+	MOV(32, R(valueReg), R(argYReg));
+	AND(8, R(valueReg), Imm8(3));
+	MOVZX(32, 16, valueReg, MComplex(gstateReg, valueReg, 4, offsetof(GPUgstate, dithmtx)));
