 void PSPOskDialog::ConvertUCS2ToUTF8(std::string& _string, wchar_t* input)
 {
 	char stringBuffer[2048];
 	char *string = stringBuffer;

 	int c;
 	while (c = *input++)
 	{
 		if (c < 0x80)
 			*string++ = c;
 		else if (c < 0x800) {
 			*string++ = 0xC0 | (c >> 6);
 			*string++ = 0x80 | (c & 0x3F);
 		} else {
 			*string++ = 0xE0 | (c >> 12);
 			*string++ = 0x80 | ((c >> 6) & 0x3F);
 			*string++ = 0x80 | (c & 0x3F);
 		}
 	}
 	*string++ = '\0';
 	_string = stringBuffer;
 }

