+				// If possible, let's do this in 1024 byte blocks.
+				if ((length & 0x3ff) == 0) {
+					u16 block[512];
+					for (int i = length - 1024, j = (length / 4) - 256; i >= 0; i -= 1024, j -= 256) {
+						memcpy(block, &tmpTexBuf32[j], 512 * sizeof(u16));
+						DeIndexTexture(&tmpTexBuf32[i], block, 512, clut);
