 void EmuScreen::darken() {
 	if (!screenManager()->topScreen()->wantBrightBackground()) {
 		UIContext &dc = *screenManager()->getUIContext();
 		uint32_t color = GetBackgroundColorWithAlpha(dc);
 		dc.Begin();
 		dc.RebindTexture();
 		dc.FillRect(UI::Drawable(color), dc.GetBounds());
 		dc.Flush();
 	}
 }

