 void DrawEngineVulkan::Resized() {
 	decJitCache_->Clear();
 	lastVTypeID_ = -1;
 	dec_ = NULL;
 	for (auto iter = decoderMap_.begin(); iter != decoderMap_.end(); iter++) {
 		delete iter->second;
 	}
 	decoderMap_.clear();
 }

 bool DrawEngineVulkan::IsCodePtrVertexDecoder(const u8 *ptr) const {
 	return decJitCache_->IsInSpace(ptr);
 }

