+static inline int CalcClipMask(const ClipCoords& v)
+{
+	int mask = 0;
+	if (v.x > v.w) mask |= CLIP_POS_X_BIT;
+	if (v.x < -v.w) mask |= CLIP_NEG_X_BIT;
+	if (v.y > v.w) mask |= CLIP_POS_Y_BIT;
+	if (v.y < -v.w) mask |= CLIP_NEG_Y_BIT;
+	if (v.z > v.w) mask |= CLIP_POS_Z_BIT;
