 	SUB(32, R(tempReg1), Imm8(1));
 	XOR(32, R(tempReg1), Imm32(0xFF000000));
 	AND(32, R(tempReg1), Imm32(0xFF000000));
 	OR(32, R(tempReg2), R(tempReg1));

